css:
@font-face { font-family: 'PM'; src: url(node_modules/@fontsource/permanent-marker/files/permanent-marker-latin-400-normal.woff2); }
@font-face { font-family: 'Kal'; src: url(node_modules/@fontsource/kalam/files/kalam-latin-700-normal.woff2); font-weight: 700; }
@font-face { font-family: 'Atk'; src: url(node_modules/@fontsource/atkinson-hyperlegible/files/atkinson-hyperlegible-latin-400-normal.woff2); font-weight: 400; }
@font-face { font-family: 'Atk'; src: url(node_modules/@fontsource/atkinson-hyperlegible/files/atkinson-hyperlegible-latin-700-normal.woff2); font-weight: 700; }
.card { background-color: #C29A63; color: #1E1A14; font-family: 'Atk'; }
.card::before { content: ''; position: absolute; inset: 0; background-image: radial-gradient(rgba(70,45,15,.28) 1.6px, transparent 2px), radial-gradient(rgba(255,240,210,.22) 1.4px, transparent 2px); background-size: 23px 23px, 31px 31px; background-position: 0 0, 11px 7px; }
.card::after { content: ''; position: absolute; inset: 34px; border: 18px solid #7A5230; pointer-events: none; }
.safe { gap: 0; }
.note { position: relative; padding: 80px 60px 60px; margin: 0 0 54px; box-shadow: 6px 10px 0 rgba(60,35,10,.35); }
.note::before { content: ''; position: absolute; top: 18px; left: 50%; width: 40px; height: 40px; margin-left: -20px; border-radius: 50%; background: #D7262E; box-shadow: 3px 5px 0 rgba(0,0,0,.35); }
.y { background: #FFE45C; } .p { background: #FF9EBB; } .m { background: #9FE6C3; } .b { background: #9CCBFF; } .w { background: #FFF8E7; }
.r1 { transform: rotate(-2deg); } .r2 { transform: rotate(1.6deg); } .r3 { transform: rotate(-1deg); } .r4 { transform: rotate(2.4deg); }
h1 { font: 400 134px/1.05 'PM'; margin: 0; }
h2 { font: 400 104px/1.05 'PM'; margin: 0 0 18px; }
.lbl { font: 700 62px/1.15 'Kal'; margin: 0 0 8px; color: #7A2E10; }
p.t { font: 400 64px/1.25 'Atk'; margin: 0; }
p.t b { font-weight: 700; }
.tag { align-self: flex-start; font: 700 56px 'Kal'; background: #1E1A14; color: #FFE45C; padding: 6px 26px 10px; margin: 0 0 40px; transform: rotate(-2deg); }
.row { display: flex; gap: 26px; align-items: center; }
.row .num { font: 400 100px/1 'PM'; min-width: 80px; color: #B4231F; }
.small { padding: 58px 46px 40px; margin-bottom: 34px; }
.small p.t { font-size: 62px; }
.hl { background: #FFE45C; padding: 0 8px; }
.end h1 { font-size: 124px; }
.handle { align-self: flex-start; font: 700 68px 'Kal'; background: #1E1A14; color: #FFF8E7; padding: 14px 30px 20px; transform: rotate(1.5deg); margin-top: 10px; }
